public class RehashBitSplitSimulator {
    public static void main(String[] args) {
        int oldCap = 16;
        int newCap = oldCap << 1; // 32

        String[] sampleKeys = {"Alpha", "Beta", "Gamma", "Delta", "Epsilon", "Zeta"};

        System.out.printf("%-10s | %-10s | %-12s | %-12s | %-10s%n", 
                          "Key", "HashCode", "Old Bucket (16)", "New Bucket (32)", "Bit-Split");
        System.out.println("-".repeat(65));

        for (String key : sampleKeys) {
            int h = key.hashCode() ^ (key.hashCode() >>> 16);
            int oldBucket = (oldCap - 1) & h;
            int newBucket = (newCap - 1) & h;
            boolean staysAtOld = (h & oldCap) == 0;

            System.out.printf("%-10s | %-10d | %-15d | %-15d | %s%n",
                              key, key.hashCode(), oldBucket, newBucket, 
                              staysAtOld ? "Stays (same)" : "Moves (+16)");
        }
    }
}

