public class CapacityOptimizer {
    public static int findOptimalCapacity(int expectedEntries, float loadFactor) {
        if (expectedEntries <= 0) return 16;
        int minRequired = (int) Math.ceil(expectedEntries / loadFactor);
        int cap = 1;
        while (cap < minRequired) {
            cap <<= 1;
        }
        return Math.max(cap, 16);
    }
}

