public class CollisionCounter {
    public static int countCollidedBuckets(int[] hashCodes, int capacity) {
        if (hashCodes == null || hashCodes.length == 0) return 0;
        int[] counts = new int[capacity];
        for (int h : hashCodes) {
            int spread = h ^ (h >>> 16);
            int bucket = (capacity - 1) & spread;
            counts[bucket]++;
        }
        int collided = 0;
        for (int c : counts) {
            if (c >= 2) collided++;
        }
        return collided;
    }
}
